// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public {
        c = new L1Block();
    }

    function testFuzz_property(
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 seq1,
        uint64 seq2,
        bytes32 batcherHash,
        uint256 overhead,
        uint256 scalar
    ) public {
        vm.assume(seq1 != seq2);

        vm.startPrank(DEPOSITOR);
        c.setL1BlockValues(number, timestamp, basefee, hash, seq1, batcherHash, overhead, scalar);
        c.setL1BlockValues(number, timestamp, basefee, hash, seq2, batcherHash, overhead, scalar);
        vm.stopPrank();

        assertTrue(c.sequenceNumber() == seq2);
    }
}
